import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cuda_source = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>

#define BM 64
#define BN 64
#define BK 16
#define TM 4
#define TN 4
#define THREADS_X 16
#define THREADS_Y 16

__global__ void matmul_kernel(const float* __restrict__ A,
                               const float* __restrict__ B,
                               float* __restrict__ C,
                               int N) {
    __shared__ float As[BM][BK];
    __shared__ float Bs[BK][BN];

    int bx = blockIdx.x;
    int by = blockIdx.y;

    int tx = threadIdx.x;
    int ty = threadIdx.y;
    int tid = ty * blockDim.x + tx;

    float acc[TM][TN];
    #pragma unroll
    for (int i = 0; i < TM; i++)
        #pragma unroll
        for (int j = 0; j < TN; j++)
            acc[i][j] = 0.0f;

    int numTiles = N / BK;

    for (int t = 0; t < numTiles; t++) {
        // Load As using vectorized float4 loads (256 threads cover BM*BK/4 = 256 float4 elements)
        {
            int row = tid / (BK / 4);
            int col = (tid % (BK / 4)) * 4;
            int global_row = by * BM + row;
            int global_col = t * BK + col;
            float4 val = *reinterpret_cast<const float4*>(&A[global_row * N + global_col]);
            *reinterpret_cast<float4*>(&As[row][col]) = val;
        }
        // Load Bs using vectorized float4 loads (256 threads cover BK*BN/4 = 256 float4 elements)
        {
            int row = tid / (BN / 4);
            int col = (tid % (BN / 4)) * 4;
            int global_row = t * BK + row;
            int global_col = bx * BN + col;
            float4 val = *reinterpret_cast<const float4*>(&B[global_row * N + global_col]);
            *reinterpret_cast<float4*>(&Bs[row][col]) = val;
        }

        __syncthreads();

        #pragma unroll
        for (int k = 0; k < BK; k++) {
            float a_frag[TM];
            float b_frag[TN];
            #pragma unroll
            for (int i = 0; i < TM; i++) a_frag[i] = As[ty * TM + i][k];
            #pragma unroll
            for (int j = 0; j < TN; j++) b_frag[j] = Bs[k][tx * TN + j];

            #pragma unroll
            for (int i = 0; i < TM; i++)
                #pragma unroll
                for (int j = 0; j < TN; j++)
                    acc[i][j] += a_frag[i] * b_frag[j];
        }

        __syncthreads();
    }

    #pragma unroll
    for (int i = 0; i < TM; i++) {
        #pragma unroll
        for (int j = 0; j < TN; j++) {
            int row = by * BM + ty * TM + i;
            int col = bx * BN + tx * TN + j;
            C[row * N + col] = acc[i][j];
        }
    }
}

torch::Tensor matmul_cuda(torch::Tensor A, torch::Tensor B) {
    A = A.contiguous();
    B = B.contiguous();
    int N = A.size(0);

    auto C = torch::empty({N, N}, A.options());

    dim3 block(THREADS_X, THREADS_Y);
    dim3 grid(N / BN, N / BM);

    matmul_kernel<<<grid, block>>>(
        A.data_ptr<float>(),
        B.data_ptr<float>(),
        C.data_ptr<float>(),
        N
    );

    return C;
}
"""

cpp_source = r"""
torch::Tensor matmul_cuda(torch::Tensor A, torch::Tensor B);
"""

matmul_module = load_inline(
    name="matmul_module",
    cpp_sources=cpp_source,
    cuda_sources=cuda_source,
    functions=["matmul_cuda"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Optimized model performing square matrix multiplication (C = A * B)
    using a custom tiled CUDA kernel.
    """
    def __init__(self):
        super(ModelNew, self).__init__()
        self.matmul_op = matmul_module

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        A = A.cuda().contiguous().float()
        B = B.cuda().contiguous().float()
        return self.matmul_op.matmul_cuda(A, B)


N = 2048 * 2


def get_inputs():
    A = torch.rand(N, N)
    B = torch.rand(N, N)
    return [A, B]


def get_init_inputs():
    return []

